     1→"use client";
     2→
     3→import React from "react";
     4→import { useTranslations, useLocale } from "next-intl";
     5→import { motion } from "framer-motion";
     6→import { Music4, Disc, Sliders, Mic2, Radio, ArrowRight, CheckCircle } from "lucide-react";
     7→import { NeoNavbar } from "../NeoNavbar";
     8→import { NeoFooter } from "../NeoFooter";
     9→import { NeoHeroSection } from "../ui/NeoHeroSection";
    10→import { NeoCard } from "../ui/NeoCard";
    11→import { BrutalistButton } from "../ui/BrutalistButton";
    12→import { NeoTag } from "../ui/NeoTag";
    13→import { Link } from "@/i18n/routing";
    14→
    15→interface Service {
    16→  id: string;
    17→  title: string;
    18→  text: string;
    19→  fullDescription?: string;
    20→  descriptionsFr?: string | null;
    21→  descriptionsEn?: string | null;
    22→}
    23→
    24→interface NeoServicesPageProps {
    25→  services: Service[];
    26→}
    27→
    28→const getIconForService = (title: string) => {
    29→  const lowerTitle = title.toLowerCase();
    30→  if (lowerTitle.includes("compo")) return Music4;
    31→  if (lowerTitle.includes("produc")) return Disc;
    32→  if (lowerTitle.includes("mix")) return Sliders;
    33→  if (lowerTitle.includes("master")) return Radio;
    34→  if (lowerTitle.includes("vocal")) return Mic2;
    35→  return Disc;
    36→};
    37→
    38→const staggerContainer = {
    39→  hidden: { opacity: 0 },
    40→  visible: {
    41→    opacity: 1,
    42→    transition: { staggerChildren: 0.15, delayChildren: 0.2 },
    43→  },
    44→};
    45→
    46→const fadeInUp = {
    47→  hidden: { opacity: 0, y: 40 },
    48→  visible: { opacity: 1, y: 0, transition: { duration: 0.6 } },
    49→};
    50→
    51→export const NeoServicesPage: React.FC<NeoServicesPageProps> = ({ services }) => {
    52→  const t = useTranslations("services");
    53→  const locale = useLocale();
    54→
    55→  const getDescription = (service: Service) => {
    56→    if (locale === "fr" && service.descriptionsFr) return service.descriptionsFr;
    57→    if (locale === "en" && service.descriptionsEn) return service.descriptionsEn;
    58→    return service.text;
    59→  };
    60→
    61→  const processSteps = [
    62→    { key: "brief", icon: "01" },
    63→    { key: "composition", icon: "02" },
    64→    { key: "production", icon: "03" },
    65→    { key: "mixing", icon: "04" },
    66→    { key: "delivery", icon: "05" },
    67→  ];
    68→
    69→  return (
    70→    <div className="min-h-screen bg-neo-bg text-neo-text font-sans selection:bg-neo-text selection:text-neo-accent overflow-x-hidden">
    71→      <NeoNavbar />
    72→
    73→      <main className="relative z-10 pt-16 md:pt-20">
    74→        {/* Hero */}
    75→        <NeoHeroSection
    76→          badgeNumber="03"
    77→          badge={t("hero.badge")}
    78→          title={t("hero.title")}
    79→          description={t("hero.description")}
    80→          fullViewport
    81→        >
    82→          <div className="flex flex-wrap gap-4">
    83→            <BrutalistButton
    84→              variant="primary"
    85→              size="lg"
    86→              icon={<ArrowRight className="w-5 h-5" />}
    87→              onClick={() =>
    88→                document.getElementById("services-list")?.scrollIntoView({ behavior: "smooth" })
    89→              }
    90→            >
    91→              {t("hero.cta")}
    92→            </BrutalistButton>
    93→            <Link href="/contact">
    94→              <BrutalistButton variant="secondary" size="lg">
    95→                {t("hero.ctaSecondary")}
    96→              </BrutalistButton>
    97→            </Link>
    98→          </div>
    99→        </NeoHeroSection>
   100→
   101→        {/* Services Grid */}
   102→        <section id="services-list" className="py-24">
   103→          <div className="container mx-auto px-4 md:px-6">
   104→            <motion.div
   105→              initial="hidden"
   106→              whileInView="visible"
   107→              viewport={{ once: true }}
   108→              variants={staggerContainer}
   109→              className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6"
   110→            >
   111→              {services.map((service, i) => {
