    33→  const normalized = style
    34→    .toLowerCase()
    35→    .normalize("NFD")
    36→    .replace(/[\u0300-\u036f]/g, "");
    37→
    38→  if (normalized.includes("metal") || normalized.includes("hardcore")) return "Metal";
    39→  if (
