    48→  if (normalized.includes("cyberpunk")) return "Cyberpunk";
    49→  if (normalized.includes("bass")) return "Bass Music";
    50→  if (normalized.includes("pop punk") || normalized.includes("punk")) return "Pop Punk";
    51→  if (normalized.includes("all music genres")) return "Various";
    52→
    53→  return style;
    54→};
    55→
    56→const sortGenres = (genres: string[]) => {
