    69→    const index = order.indexOf(genre);
    70→    return index === -1 ? Number.POSITIVE_INFINITY : index;
    71→  };
    72→
    73→  return [...genres].sort((a, b) => {
    74→    const byOrder = orderIndex(a) - orderIndex(b);
    75→    if (byOrder !== 0) return byOrder;
    76→    return a.localeCompare(b);
    77→  });
    78→};
